package com.lobbykin;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.time.Instant;
import javax.imageio.ImageIO;
import javax.swing.*;
import org.junit.Test;
import static org.junit.Assert.*;
/** Actual Swing rendering at RuneLite's 225px content width, with adversarial labels. */
public class SidebarVisualTest {
 private static final String ID="11111111-1111-4111-8111-111111111111";
 private SessionSnapshot sample(int count,boolean started){
  StringBuilder members=new StringBuilder();for(int i=0;i<count;i++){if(i>0)members.append(',');members.append("{\"name\":\"").append(i==0?"GIM Jusky":i==1?"Long Character Name":"Teammate "+i).append("\",\"role\":\"").append(i==0?"Host":"Member").append("\",\"ready\":").append(i!=0).append('}');}
  return SessionSnapshot.parse(new com.google.gson.Gson(), "{\"account\":\"GIM Jusky\",\"scope\":\"sessions:read\",\"sessions\":[{\"id\":\""+ID+"\",\"title\":\"Learning together – relaxed evening runs\",\"activity\":\"ToA\",\"session_type\":\"Learning\",\"my_status\":\"host\",\"world\":360,\"raid_phase\":\""+(started?"started":"waiting")+"\",\"my_ready\":false,\"can_set_ready\":true,\"can_track\":true,\"ready_count\":"+(count-1)+",\"team_size\":"+count+",\"members\":["+members+"]},{\"id\":\"22222222-2222-4222-8222-222222222222\",\"title\":\"Tomorrow with friends\",\"activity\":\"CoX\",\"my_status\":\"accepted\",\"start_at\":\"2099-01-01T19:00:00Z\"}]}");
 }
 private void layout(Container c){c.doLayout();for(Component child:c.getComponents())if(child instanceof Container)layout((Container)child);}
 private void bounds(Container c){for(Component x:c.getComponents())if(x.isVisible()){assertTrue(x.getClass()+" left",x.getX()>=0);assertTrue(x.getClass()+" right "+(x.getX()+x.getWidth())+">"+c.getWidth(),x.getX()+x.getWidth()<=c.getWidth());if(x instanceof Container)bounds((Container)x);}}
 private void render(LobbykinPanel p,String name)throws Exception{p.setSize(225,1000);for(int i=0;i<3;i++){layout(p);p.setSize(225,p.getPreferredSize().height);}layout(p);bounds(p);BufferedImage img=new BufferedImage(225,p.getHeight(),BufferedImage.TYPE_INT_RGB);Graphics2D g=img.createGraphics();p.printAll(g);g.dispose();File out=new File("build/reports/sidebar/"+name+".png");out.getParentFile().mkdirs();ImageIO.write(img,"png",out);p.dispose();}
 @Test public void actualPanelFitsRuneLiteWidthForLongNamesAndFourOrEightMembers()throws Exception{SwingUtilities.invokeAndWait(()->{try{UIManager.setLookAndFeel(new com.formdev.flatlaf.FlatDarkLaf());for(int n:new int[]{4,8}){LobbykinPanel p=new LobbykinPanel(()->{});p.showPlayer("GIM Jusky",350);p.showSessions(sample(n,false),Instant.parse("2026-10-29T12:00:00Z"));render(p,"preparing-"+n);}LobbykinPanel p=new LobbykinPanel(()->{});p.showPlayer("GIM Jusky",350);p.showSessions(sample(4,true),Instant.parse("2026-10-29T12:00:00Z"));render(p,"started-4");p=new LobbykinPanel(()->{});p.showPlayer("GIM Jusky",350);p.showSessions(SessionSnapshot.parse(new com.google.gson.Gson(), "{\"account\":\"GIM Jusky\",\"scope\":\"sessions:read\",\"sessions\":[]}"),Instant.parse("2026-10-29T12:00:00Z"));render(p,"empty");}catch(Exception e){throw new RuntimeException(e);}});}
 @Test public void readableFontsAndWorldMismatchAreVisibleWithoutOpeningDetails()throws Exception{SwingUtilities.invokeAndWait(()->{LobbykinPanel p=new LobbykinPanel(()->{});p.showPlayer("GIM Jusky",461);p.showSessions(sample(4,false),Instant.now());assertTrue(hasText(p,"Wrong world: you are on 461"));assertTrue(hasText(p,"NOT TRACKING"));assertDisabled(p,"Track this session");assertReadable(p);p.dispose();});}
 @Test public void trackingAttemptRemainsVisibleWhenAListingTemporarilyDisappears()throws Exception{SwingUtilities.invokeAndWait(()->{LobbykinPanel p=new LobbykinPanel(()->{});p.showPlayer("GIM Jusky",360);p.showSessions(sample(4,false),Instant.now());p.showTrackingStatus(ID,"Raid started · ToA",true);p.showSessions(SessionSnapshot.parse(new com.google.gson.Gson(), "{\"account\":\"GIM Jusky\",\"scope\":\"sessions:read\",\"sessions\":[]}"),Instant.now());assertTrue(hasText(p,"Session temporarily unavailable"));assertTrue(hasText(p,"Raid started"));assertTrue(hasButton(p,"Stop tracking"));assertFalse(hasButton(p,"Mark ready"));p.showTrackingStatus(null,"Tracking stopped",false);assertFalse(hasButton(p,"Stop tracking"));p.dispose();});}
 private boolean hasText(Container c,String text){for(Component x:c.getComponents()){if(x instanceof JLabel&&((JLabel)x).getText()!=null&&((JLabel)x).getText().contains(text))return true;if(x instanceof JTextArea&&((JTextArea)x).getText().contains(text))return true;if(x instanceof Container&&hasText((Container)x,text))return true;}return false;}
 @Test public void diagnosticsAreCollapsedAndCompletionAcknowledgementClearsPendingCopy()throws Exception{SwingUtilities.invokeAndWait(()->{LobbykinPanel p=new LobbykinPanel(()->{});p.showPlayer("GIM Jusky",360);SessionSnapshot snap=sample(1,false);SessionSnapshot.Tracking totals=new SessionSnapshot.Tracking();totals.deaths=3;totals.failed_runs=2;totals.completed_runs=1;snap.sessions.get(0).tracking=totals;p.showSessions(snap,Instant.now());p.showTrackingStatus(ID,"Completion signal recorded · waiting for server confirmation. Session remains open.",false);p.showDetectorStatus(ID,"Detector: ToA · region=13454");p.showReportStatus(ID,"completed","queued");assertTrue(visibleText(p,"waiting for server confirmation"));p.showReportStatus(ID,"completed","ACK · server confirmed");assertTrue(visibleText(p,"Raid completed · saved to Lobbykin."));assertFalse(visibleText(p,"waiting for server confirmation"));assertFalse(visibleText(p,"Detector:"));assertFalse(visibleText(p,"Upload:"));assertTrue(visibleText(p,"Deaths"));assertTrue(visibleText(p,"Failed / left"));assertTrue(visibleText(p,"Completed"));JToggleButton details=findToggle(p,"Session details");assertNotNull(details);details.doClick();JToggleButton diagnostic=findToggle(p,"Technical diagnostics");assertNotNull(diagnostic);assertFalse(diagnostic.isSelected());assertFalse(visibleText(p,"Detector:"));diagnostic.doClick();assertTrue(visibleText(p,"Detector:"));assertTrue(visibleText(p,"Upload: completed"));snap.sessions.get(0).raid_phase="completed";p.showSessions(snap,Instant.now());assertTrue(findToggle(p,"Technical diagnostics").isSelected());findToggle(p,"Session details").doClick();try{render(p,"completed-clean");}catch(Exception e){throw new RuntimeException(e);}p.dispose();});}
 private boolean visibleText(Container c,String text){for(Component x:c.getComponents())if(x.isVisible()){if(x instanceof JLabel&&((JLabel)x).getText()!=null&&((JLabel)x).getText().contains(text))return true;if(x instanceof JTextArea&&((JTextArea)x).getText().contains(text))return true;if(x instanceof Container&&visibleText((Container)x,text))return true;}return false;}
 private JToggleButton findToggle(Container c,String text){for(Component x:c.getComponents()){if(x instanceof JToggleButton&&((JToggleButton)x).getText().contains(text))return (JToggleButton)x;if(x instanceof Container){JToggleButton found=findToggle((Container)x,text);if(found!=null)return found;}}return null;}
 private boolean hasButton(Container c,String text){for(Component x:c.getComponents()){if(x instanceof JButton&&text.equals(((JButton)x).getText()))return true;if(x instanceof Container&&hasButton((Container)x,text))return true;}return false;}
 private void assertReadable(Container c){for(Component x:c.getComponents()){if(x instanceof JLabel||x instanceof JTextArea||x instanceof JButton||x instanceof JToggleButton){assertTrue(Font.SANS_SERIF.equalsIgnoreCase(x.getFont().getName()));assertTrue(x.getFont().getSize()>=12);}if(x instanceof Container)assertReadable((Container)x);}}
 @Test public void totalsAndIndependentDetectorUploadDiagnosticsAreVisible()throws Exception{SwingUtilities.invokeAndWait(()->{try{LobbykinPanel p=new LobbykinPanel(()->{});p.showPlayer("GIM Jusky",360);SessionSnapshot snap=sample(1,true);SessionSnapshot.Tracking totals=new SessionSnapshot.Tracking();totals.deaths=3;totals.failed_runs=1;totals.interrupted_runs=2;totals.completed_runs=2;snap.sessions.get(0).tracking=totals;p.showSessions(snap,Instant.now());p.showTrackingStatus(ID,"Raid started · ToA",true);p.showDetectorStatus(ID,"Detector: ToA · party=1 · instance=true · region=14160 · in raid=true");p.showReportStatus(ID,"started","ACK · server confirmed");p.showReportStatus(ID,"heartbeat","error · retry queued");assertTrue(hasText(p,"Deaths"));assertTrue(hasText(p,"Failed / left"));assertTrue(hasText(p,"Completed"));assertTrue(hasText(p,"Start upload: ACK"));assertTrue(hasText(p,"heartbeat · error"));assertTrue(hasText(p,"Raid started · ToA"));render(p,"tracking-diagnostics");}catch(Exception e){throw new RuntimeException(e);}});}
 @Test public void staleDataCannotIssueHopOrReady()throws Exception{SwingUtilities.invokeAndWait(()->{LobbykinPanel p=new LobbykinPanel(()->{});p.showPlayer("GIM Jusky",350);p.showSessions(sample(4,false),Instant.now());p.showError("Offline");assertDisabled(p,"Hop to 360");assertDisabled(p,"Mark ready");p.dispose();});}
 private void assertDisabled(Container c,String text){for(Component x:c.getComponents()){if(x instanceof JButton&&text.equals(((JButton)x).getText()))assertFalse(((JButton)x).isEnabled());if(x instanceof Container)assertDisabled((Container)x,text);}}
}
